/* Exam case studies (paraphrased from oral exam protocols + new practice cases; numbers marked as fictive) */
(function () {
  const A = window.AEA;
  const C = (o) => A.cases.push(o);
  const P = (topic, q, k, fu, trap) => ({ who: 'P', topic, q, k, fu: fu || [], trap });
  const B = (topic, q, k, fu, trap) => ({ who: 'B', topic, q, k, fu: fu || [], trap });

  C({ id: 'banknotes', icon: '💵', title: 'Danish banknotes (cotton-based security paper)', src: 'Exam HS21, paraphrased',
    intro: '<p>Danmarks Nationalbank (DN) needs new banknotes and first wants an LCA of its current notes. <b>Cotton</b> is grown and ginned: lint goes to textiles, <b>linters</b> and cotton seed are by-products; combers from spinning are also used. A paper mill produces the <b>security paper</b>, a printer prints the notes (intaglio, offset, varnish – <b>VOC emissions</b>). Notes circulate for a few years and are finally shredded and <b>incinerated</b> in a municipal plant that sells <b>electricity</b> to the utility and <b>steam</b> to the district heating network. Many different suppliers deliver linters and combers. A polymer note is discussed as an alternative.</p><p class="small muted">Ginning data (fictive exercise values, per t seed cotton, 50 kWh electricity):</p>',
    data: [['Output', 'Amount', 'Price'], ['Lint (textile fibre)', '350 kg', '1.60 CHF/kg'], ['Linters (for security paper)', '80 kg', '0.40 CHF/kg'], ['Cotton seed (oil, feed)', '540 kg', '0.25 CHF/kg'], ['Waste', '30 kg', '–']],
    fig: 'banknote',
    tips: 'A classic. Lessons from the feedback: FU not based on mass; ISO allocation terms exactly; uncertainty types + pedigree ≠ Monte Carlo; product LCA ≠ bank footprint.',
    q: [
      P('fu', 'Propose a functional unit appropriate for the LCA of the Danish banknotes and give reasons.', ['Function: means of payment / value in circulation – not mass', 'e.g. "use of one 200-DKK note (or a set of all denominations) in circulation during one year"', 'Time dimension needed: lifetimes of cotton vs. polymer notes differ', 'Quality: same security features and handling', 'Reference flow = 1/lifetime notes per year (+ production, distribution, destruction)'], [['What if you compare cotton with polymer notes – would you add something?', 'The time dimension (lifetime) – otherwise a durable note is disadvantaged.']], '1 g or 1 kg of banknotes (real grade 4.0).'),
      P('lcia', 'Which impact categories would you consider in this LCA, and why?', ['Water scarcity (irrigated cotton; regionalized, AWARE)', 'Land use → biodiversity loss', 'Ecotoxicity & human toxicity (pesticides, inks, VOC)', 'Climate change (energy for paper making, printing, transport, incineration)', 'Eutrophication (fertilizer), particulate matter', 'Chosen by hotspots and goal; avoid carbon-only (burden shifting)'], [['Is land use an environmental impact?', 'No, it is the intervention; the impact is biodiversity (ecosystem) loss and soil degradation.']]),
      P('alloc', 'The incineration plant treats the notes and sells electricity and steam. Which allocation options does ISO 14044 recommend? How would you perform the allocation and why?', ['ISO: (1) avoid – subdivision or system expansion; (2) physical relationships; (3) other relationships (economic)', 'Subdivision hardly possible → system expansion/substitution', 'Data: impacts of incinerating 1 t notes; electricity (kWh) and steam (MJ) delivered per t', 'Credits = amounts × impacts of displaced electricity (marginal/average) and heat (e.g. gas boiler in district heating)', 'Net can be negative; alternatively partition by energy/exergy or revenue; sensitivity'], [['What if more electricity is produced than consumed in the banknote life cycle?', 'You credit avoided production elsewhere – the net result becomes negative; you do not just subtract it from own consumption.']], 'Calling cut-off/EOR "physical allocation".'),
      P('alloc', 'Ginning produces lint, linters and cotton seed. How much of the ginning burden would the linters carry with mass vs. economic allocation (see table)?', ['Avoid first: subdivision not possible (one process) → system expansion would need substitutes for lint and seed', 'Mass: 80 / 970 ≈ 8.2 %', 'Economic: revenues 560 + 32 + 135 = 727 CHF → linters 32/727 ≈ 4.4 %', 'Linters are a low-value by-product → economic allocation gives them less', 'Choice changes the result → sensitivity analysis, document'], [['Which method would you choose?', 'Economic reflects why ginning happens (lint); show mass as sensitivity.']]),
      P('unc', 'There are many suppliers of linters and combers. Which uncertainties arise and how do you consider them? Name the type of uncertainty related to supplier data.', ['Variability between sources/suppliers (technology, region, yields, energy) → uncertainty while the mix is unknown', 'Reducible with supplier-specific data and actual shares', 'Other types: parameter, model, scenario uncertainty; spatial and temporal variability', 'Characterize: distributions from supplier data or pedigree matrix', 'Propagate: Monte Carlo (inputs = distributions; output = result distribution); plus scenarios and sensitivity'], [['What are inputs and outputs of the Monte Carlo simulation?', 'Inputs: probability distributions of all uncertain parameters; output: a distribution of the LCA result; no specific distribution form needed.']], 'Confusing pedigree and Monte Carlo (real grade 2.5).'),
      P('review', 'A critical review according to ISO 14040/44 has to be performed. What is the procedure, what is checked, which skills must the reviewers have?', ['Procedure: appoint panel at start → goal & scope review → data review → draft report → comments → revised report → final report with review statement', 'Checked: ISO consistency, scientific/technical validity, data appropriate for the goal, interpretation reflects limitations, transparency & consistency', 'Not: goal or use of results', 'Skills: independence, language, LCA methodology, review/audit experience, sector expertise (paper, printing)', 'Mandatory for public comparative assertions (cotton vs. polymer!) → panel'], [['Is a critical review needed to display information to the public?', 'Mandatory only for comparative assertions disclosed to the public; otherwise recommended.']]),
      P('risk', 'There are VOC emissions at the printer, a risk for human health. Which information do you gather to analyse the indoor exposure and the health risk?', ['Emission rates (measurements), number and position of sources', 'Room volume, ventilation rate, mixing', 'Worker behaviour: distance, duration', 'Model via decision tree: one-box (C = E/Q) → near-/far-field → eddy diffusion', 'Effect data: limits/NOEC → RQ; in LCA: DALY'], [['How do you compute the concentration in the box model?', 'C = E / (ACH × V) at steady state.']]),
      B('company', 'Discuss the relevance of banknote production for the environmental performance of DN. Which additional information do you need?', ['Product LCA and company footprint only partly overlap (paper and printing partly outside DN; DN has many other activities)', 'Need data on all relevant DN activities: Scope 1, 2, 3 or a company ecobalance', 'Avoid double counting of storage/distribution', 'Discuss units: CO₂-eq, UBP, MJ, CHF – pros and cons', 'Then set priorities in the EMS'], [['In which units would you express relevance?', 'Several, and discuss: CO₂-eq (climate only), UBP (broad, weighted), MJ (energy), CHF (management leverage).']], 'Not mentioning the overlap (real grade 4.25).'),
      B('ems', 'DN wants to include the LCA in its environmental management. Explain this with the Deming circle. What else is needed for an EMS?', ['PDCA: Plan – hotspots, significant aspects, SMART targets (e.g. −20 % VOC at printing by 2029); Do – eco-design, supplier requirements; Check – update LCA, KPIs; Act – management review', 'Alternatively: LCA procedure itself is iterative', 'Other EMS elements: policy, organisation & responsibilities, compliance obligations, programmes, training, documentation, audits, management review'], [['Apart from the circle, what other parts are needed?', 'Policy, organisation, aspects, compliance, targets & programmes, resources, documentation, audits, review.']]),
    ] });

  C({ id: 'windows', icon: '🪟', title: 'Window frames for "BuilderBob"', src: 'Exams HS19 / FS11, paraphrased',
    intro: '<p>You work for <b>BuilderBob</b>, which sells building equipment including window frames, and recently decided to become "<b>the environmental construction supplier</b>". It commissions an LCA of window frames. Standard windows: 1.75 m × 1.30 m, two wings, identical double glazing. Frames: <b>aluminium</b>, <b>wood</b>, <b>wood with aluminium weather protection</b>, <b>PVC</b>. In production, <b>sawdust and wood chips</b> are used for heat. Windows lose much less energy than decades ago (now only 1.5× the losses of a wall instead of 2×), so architects design <b>larger windows</b>. Some windows are installed near <b>busy streets</b>.</p>',
    tips: 'First Pfister (FU, uncertainty, review, allocation, rebound, noise, optimization), then Braunschweig (LCC, targets, LCA in the company).',
    q: [
      P('fu', 'Define an appropriate functional unit for the LCA of window frames.', ['One window 1.75 × 1.30 m, two wings, identical glazing and thermal performance (U-value)', 'Installed and used over a fixed period (e.g. 30–40 years) incl. maintenance and replacements', 'Equal function: insulation, air tightness, durability', 'Reference flows: frames needed in the period (lifetimes differ)'], []),
      P('unc', 'Give examples of parameter uncertainties you would consider and how you would quantify them.', ['Lifetime of frames, maintenance intervals (painting wood)', 'U-value and resulting heat losses, heating system and fuel mix', 'Recycling rates (aluminium, PVC), transport distances', 'Material amounts per frame, emission factors', 'Quantify: measurements/literature ranges → distributions, pedigree matrix; propagate with Monte Carlo; sensitivity analysis'], []),
      P('review', 'The comparative LCA shall undergo a critical review. Explain procedure, requirements and contents. Which elements are particularly sensitive?', ['Mandatory panel review (public comparative assertion); appointed at start; iterative procedure', 'Checks: ISO consistency, validity, data appropriateness, interpretation, transparency', 'Sensitive: FU (lifetime, maintenance), use phase heat losses, aluminium recycling allocation (cut-off vs. EOR!), data representativeness, impact categories (PVC additives, land use for wood), no weighting', 'Sensitivity and uncertainty analysis required'], []),
      P('alloc', 'Sawdust and wood chips from production are used for heat. How do you allocate?', ['Multi-output process (sawing)', 'System expansion: credit avoided heat (fuel replaced: oil/gas)', 'Physical (mass/energy) would burden by-products heavily', 'Economic: low value of sawdust → small share', 'Sensitivity analysis'], []),
      P('clca', 'How would you include the rebound effect (larger windows) in the comparative LCA? Start with the term.', ['Rebound: efficiency gains lead to more consumption, offsetting savings', 'Here: better windows → more window area replaces wall (direct rebound in design)', 'Expand the system to the façade/building; FU e.g. heating & lighting a building or 1 m² façade', 'Scenarios with larger window shares; consequential view; market data on design trends', 'Show results with and without rebound'], []),
      P('risk', 'Windows near a busy street: how would you quantify the noise impact on human health?', ['Source (traffic noise) → propagation (distance, façade/window insulation) → exposure (level at receptor, number of people, time) → effect (annoyance, sleep disturbance, cardiovascular)', 'Exposure-response functions', 'DALY via disability weights', 'Analogy to indoor air model'], []),
      P('dec', 'You want to refurbish a family house (windows, heat supply, PV vs. grid, insulation). Formulate an optimization problem for the most eco-efficient solution.', ['Variables: window type, insulation thickness, heat pump/solar thermal, PV area', 'Objective: max eco-efficiency (benefit/cost) or min impact s.t. budget', 'Constraints: heat demand covered; PV area ≤ roof; budget ≤ B; one window type; legal U-values', 'LCA matrix data + LCC data', 'Pareto front, sensitivity'], []),
      B('lcc', 'You set up an LCC for the window frames. What do you include for market cost only? What would you add for ecological aspects?', ['Market: purchase, installation, maintenance (painting), repairs, heating energy losses over lifetime, replacement, disposal; discounting', 'Same function and period', 'Ecological: external costs (CO₂ from heating and production, air pollution, resources) e.g. with a CO₂ price or monetized LCA', 'No discounting of environmental costs', 'Portfolio LCC vs. LCA'], []),
      B('targets', 'BuilderBob\'s management asks you to define environmental goals and targets to become "the environmental construction supplier". Propose three and discuss them.', ['Product range: share of products with EPD/ecolabel ≥ 50 % of sales by 2028', 'Own operations: Scope 1+2 −30 % by 2030 vs. 2025 (logistics, heating, PV)', 'Customer advice: LCA/LCC advice in ≥ 80 % of large projects by 2027 (train sales staff)', 'Check SMART, relevance (products = Scope 3 dominate), responsibilities, monitoring', 'Embed in ISO 14001 cycle'], []),
      B('company', 'What are the steps to become an environmentally friendly company, and how can BuilderBob use the LCA?', ['Responsible person close to CEO, working group, budget', 'Aspects & stakeholders, compliance, policy, SMART targets, KPIs, PDCA (ISO 14001)', 'LCA use: product range decisions, supplier requirements, eco-design, customer advice, marketing (EPD), monitoring', 'Communicate strengths and weaknesses honestly (no greenwashing)'], []),
    ] });

  C({ id: 'salmon', icon: '🐟', title: 'Salmon farming & processing company XY', src: 'Exam HS16, paraphrased',
    intro: '<p>LCAs of salmon farming in <b>Norway, UK, Canada and Chile</b> (FU: 1 t salmon; network of unit processes with system boundary given). Inventory: feed quantity, energy for feeding, transport of feed and eggs, feed composition (oil from crops, animals, fish). Results for climate change and eutrophication: <b>Norway clearly lowest</b>. Farms use <b>antibiotics</b>; infrastructure was not included.</p><p>Company <b>XY</b> processes <b>300 t salmon/year</b> (main supplier UK, 20 % from Chile). Cooling and smoking need <b>3 GWh/year</b>; about 10 % of its "impact" is business travel. 1 t salmon yields <b>750 kg fillet, 150 kg cat food, 100 kg fish food</b>. XY sells 2 % MSC salmon but is not ISO 14001 certified.</p><p class="small muted">Fictive illustration of the results:</p>',
    data: [['Country', 'Feed [t/t salmon]', 'GHG [kg CO₂-eq/t]', 'Eutroph. [kg PO₄-eq/t]'], ['Norway', '1.15', '2,000', '25'], ['UK', '1.35', '2,900', '40'], ['Canada', '1.30', '2,700', '38'], ['Chile', '1.45', '3,100', '45']],
    tips: '50 % Pfister/Hellweg topics, 50 % Braunschweig. Energy question: compare the company and the supply chain in the same unit!',
    q: [
      P('fu', 'The study uses "1 t of salmon" as functional unit. Is this appropriate? How would you define it for XY\'s products or for a comparison with other protein sources?', ['For comparing farming countries: 1 t live-weight salmon at farm gate is OK (same product)', 'Specify: live weight vs. gutted vs. fillet, quality, delivered where', 'For XY\'s products: 1 kg fillet (smoked) at the gate, with allocation of co-products', 'For protein comparison: per kg protein or nutritional value (sensitivity)'], []),
      P('basics', 'Why is the impact in Norway considerably lower than in the other countries?', ['Lower feed conversion ratio (less feed per t salmon) → less feed production impacts', 'Less energy for feeding; possibly cleaner electricity (hydro)', 'Feed composition: less animal oil/fish oil → lower eutrophication and GHG', 'Shorter transports of feed/eggs', 'Check data quality and representativeness before concluding'], []),
      P('alloc', 'From 1 t salmon we get 750 kg fillet, 150 kg cat food and 100 kg fish food. How do you deal with this multifunctional process? List approaches with pros and cons.', ['ISO: subdivision (separate lines) or system expansion (credit avoided cat food / fish meal)', 'Mass allocation: simple, but ignores value (fillet 75 %)', 'Economic: reflects why the process runs (fillet ~97 %), prices fluctuate', 'Energy/protein content as physical alternatives', 'Sensitivity analysis, document'], [['Which does ISO propose?', 'The three-step hierarchy: avoid → physical → other (economic).']]),
      P('io', 'Why was infrastructure not included? How could it be included without knowing the whole supply chain?', ['Data gaps, effort, assumed small; "sunk impacts" of existing infrastructure', 'Hybrid LCA: IO data for capital goods', 'Spending on infrastructure (cages, boats, buildings, roads) × sector emission intensity (EE-IO)', 'Annualize over lifetime and relate to the FU', 'Check relevance with sensitivity analysis'], [['Which information do you need for an IO-LCA?', 'Spending per sector (e.g. construction costs), price year, IO table with satellite data.']]),
      P('unc', 'How would you check the uncertainty of this study?', ['Identify uncertain parameters: feed amounts, antibiotic emissions, energy, emission factors, yields', 'Assign distributions (data or pedigree)', 'Matrix model h = Q·B·A⁻¹·f; Monte Carlo → distribution of h', 'Mean, SD, percentiles; compare countries with dependent sampling', 'Sensitivity analysis on key parameters'], []),
      P('lcia', 'The farms use antibiotics. How do you deal with that in the LCA?', ['Emission rate ≠ concentration: fate modelling (degradation, dilution, sediment)', 'Exposure of organisms (and humans via fish)', 'Effect: ecotoxicity (USEtox CTUe, EC50/HC50); mixtures → concentration addition Σ C/EC50', 'Data gaps; antibiotic resistance not in LCIA → complement with RA', 'Regional: depends on the water body'], [['Is the emission rate the same as the concentration?', 'No – a fate/dispersion model and the mixing conditions are needed.']]),
      B('ems', 'Which certificates should company XY use? Explain them.', ['ISO 14001 (EMS, aspects, targets, PDCA)', 'ISO 14064-1 (GHG inventory) – high GHG relevance', 'SA8000 for social risks with Chilean suppliers; requires supplier certification → propagates', 'ISO 50001 (3 GWh energy)', 'ASC/MSC product labels; ISO 22000 food safety'], [['Would you add another norm?', 'ISO 14001 for the management system; ISO 50001 for energy.']]),
      B('company', 'If you had to consult XY on energy demand, would you focus on the company itself or on the supply chain? Arguments?', ['Compare in the same unit: own 3 GWh/300 t = 10 MWh/t vs. upstream energy per t from the LCA', 'Convert to primary energy or CO₂-eq', 'Feed production usually dominates → supplier choice (Norway), feed composition', 'Own energy is directly controllable → efficiency, renewable electricity', 'Scope logic: own = Scope 1/2, supply chain = Scope 3'], [['What additional information would you need?', 'Energy data of the supply chain in the same unit (e.g. MJ or kg CO₂-eq per t).']]),
      B('ems', 'XY sells 2 % MSC salmon but is not ISO 14001 certified. How can this be explained?', ['MSC certifies products (sustainable fishery, chain of custody)', 'ISO 14001 certifies the management system of the organisation, not products or performance', 'Independent instruments: possible to have one without the other', 'MSC share small → no indication of overall environmental management'], []),
      B('econ', 'Salmon farming is very important for Chile\'s economy; its GDP doubled in 20 years, but environmental problems grew. How can you explain that?', ['GDP measures market transactions (flows), not changes in natural capital', 'Degradation of water quality and ecosystems is not deducted (external costs)', 'Damages do not reduce GDP; clean-up even increases it', 'Need indicators beyond GDP (MONET, satellite accounts) and internalization'], []),
    ] });

  C({ id: 'pv', icon: '☀️', title: 'PV on the roof: modules vs. integrated solar tiles', src: 'Older protocol, paraphrased',
    intro: '<p>Two photovoltaic systems for a house: <b>(A)</b> conventional modules mounted on the existing tiled roof; <b>(B)</b> building-integrated PV <b>roof tiles</b> that replace the normal tiles. LCA results are available for <b>climate change</b> and <b>freshwater ecotoxicity</b>. The aluminium frames of system A are recycled at end of life.</p><p>Second part: a large <b>engineering consultancy</b> (quarterly meetings of its quality managers) wants to implement <b>ISO 14001</b>.</p>',
    tips: 'Treat the multifunctionality (roof function) like an allocation question. Go into detail on the climate cause–effect chain and the DALY.',
    q: [
      P('fu', 'What would be the functional unit?', ['1 kWh of electricity delivered (household/grid)', 'Equal roofing function: system B also replaces roof tiles', 'Lifetime/yield over e.g. 25–30 years, location (irradiation)', 'Alternatively: electricity + 1 m² roof over 30 years'], []),
      P('alloc', 'System B replaces roof tiles, system A needs them. How do you solve that?', ['Multifunctionality: B delivers electricity + roofing', 'System expansion: add roof tiles to system A (or credit avoided tiles to B)', 'Or include both functions in the FU', 'Allocation by economic value as fallback', 'Explain details: which tiles, lifetime, amounts'], []),
      P('lcia', 'Which impact categories contribute to the damage category human health?', ['Climate change (via temperature: malnutrition, malaria, heat)', 'Particulate matter (PM2.5, secondary from NOx/SO₂/NH₃)', 'Human toxicity (cancer, non-cancer)', 'Ozone depletion, photochemical ozone, ionising radiation', 'Water scarcity (malnutrition)', 'Unit DALY'], []),
      P('lcia', 'Is regionalization important for this case? Why?', ['Climate change: global – no regionalization of CFs', 'Ecotoxicity (production of modules, metals), PM, water for silicon production: regional', 'Production often in China: regionalized LCI (grid mix, emissions) and CFs', 'Irradiation at the installation site determines the yield (LCI regionalization)'], []),
      P('lcia', 'Describe the cause-effect pathway of greenhouse gases.', ['Emission → atmospheric concentration (lifetimes, CO₂ decay) → radiative forcing → temperature → damages (DALY, species loss)', 'Midpoint GWP (or GTP), endpoint human health/ecosystems', 'Time horizon as value choice', 'Different degradation: CH₄ ~12 a vs. CO₂ partly centuries'], [['What about the degradation of CO₂ and other gases?', 'CO₂ has no single lifetime (multi-exponential, part stays for centuries); CH₄ ~12 a; N₂O ~110 a.']]),
      P('lcia', 'Human health: what is a DALY?', ['Disability-adjusted life years = YLL + YLD', 'YLL = deaths × remaining life expectancy', 'YLD = cases × duration × disability weight', '1 DALY = 1 lost year of healthy life'], []),
      P('alloc', 'At end of life, the aluminium is recycled. Discuss demand and price changes of aluminium in this context.', ['Recycling allocation: cut-off vs. avoided burden', 'Consequential view: more scrap supply → lower scrap price → does it really displace primary aluminium?', 'Primary aluminium production is driven by demand; secondary aluminium is constrained by scrap availability', 'Credit only if recycled aluminium replaces primary on the market', 'Market effects and price elasticity'], []),
      B('ems', 'The consultancy wants to implement ISO 14001. How would you proceed?', ['Top management commitment, responsible person close to CEO, working group', 'Context and stakeholders, compliance obligations, environmental policy', 'Significant aspects of a consultancy: business travel, offices (energy, IT), paper, commuting – and indirect aspects: the advice given to clients!', 'SMART targets and programmes; integrate into existing quality meetings (ISO 9001)', 'Monitoring, internal audits, management review, certification'], []),
      B('supply', 'Would SA8000 be a good idea for this company? Why? What does it say?', ['SA8000: certifiable social standard (ILO conventions, human rights): no child/forced labour, health & safety, working hours, wages, freedom of association', 'For an office-based consultancy in Switzerland: low direct risk, limited benefit', 'Relevant for suppliers (e.g. PV supply chain, polysilicon) → supplier code of conduct', 'Certified companies require suppliers to be certified'], []),
      B('targets', 'Propose an environmental target for the company.', ['e.g. "Reduce business-travel emissions per employee by 25 % by 2028 vs. 2025 (more video calls, train for trips < 6 h); responsible: COO"', 'Check SMART criteria', 'Relevance: business travel is a main aspect of consultancies', 'Monitoring via travel agency data'], []),
    ] });

  C({ id: 'lithium', icon: '🔋', title: 'Lithium for batteries: brines vs. hard rock', src: 'Exam HS18, paraphrased',
    intro: '<p>Lithium for electric-vehicle batteries is produced either from <b>salt brines</b> (evaporation ponds in arid regions, e.g. Atacama) or from <b>hard rock</b> (spodumene mining, e.g. Australia, refining often in China). Data are available on the amount of lithium produced and the <b>freshwater</b> needed at different sites. A company extracting lithium uses the <b>GHG Protocol</b> and the <b>Swiss ecological scarcity method</b>.</p><p class="small muted">Fictive site data:</p>',
    data: [['Site', 'Production [t Li₂CO₃/a]', 'Freshwater [m³/t]', 'AWARE CF'], ['Brine, Atacama', '20,000', '50', '90'], ['Hard rock, Australia', '30,000', '80', '30'], ['Refining, China', '–', '20', '40']],
    tips: 'The IO/rebound question ("an EV saves money") and the regionalization of water are the crux.',
    q: [
      P('fu', 'Define a functional unit to compare the battery types.', ['Storage of 1 kWh electricity over the battery lifetime (or 1 km driven by a defined EV)', 'Same capacity, cycle life, performance', 'Lithium itself is only an intermediate → FU at battery/service level', 'Reference flow: kg Li₂CO₃ per kWh capacity'], []),
      P('io', 'When you drive an electric car you save money. How would you use an environmental IO table? What information do you need?', ['Rebound: saved money is re-spent', 'Re-spending × average consumption intensity (kg CO₂-eq/CHF) from EE-IO (or by spending category)', 'Need: amount saved, household spending structure, IO table with satellite data, price year', 'Consequential perspective; compare with direct savings'], [['Explain the consequential LCA and the equation.', 'Model changes due to the decision with marginal data; e = d·(I − A)⁻¹·Δy for the re-spending.']]),
      P('lcia', 'Mining poses risks for freshwater. How do you assess them?', ['Water consumption (evaporation of brine!) × regional scarcity CF (AWARE)', 'Ecosystem impacts: wetlands, groundwater tables, flamingos/species', 'Human health: water for local communities and agriculture', 'Water quality: toxicity of process chemicals (risk assessment, USEtox)', 'Regionalized LCI and LCIA needed'], []),
      P('unc', 'Using the site data, how would you create a global indicator (e.g. water scarcity per kg lithium)? How do you deal with the variability?', ['Production-weighted average of site-specific impacts (consumption × CF)', 'Spatial variability between sites; uncertainty of data', 'Best/worst case (boundary analysis), Monte Carlo with distributions', 'Report range and mean, not only one value'], []),
      B('ems', 'You have a company extracting lithium. How would you implement ISO 14001 and SA8000?', ['ISO 14001: context (local communities, indigenous peoples, authorities), compliance, policy, significant aspects (water, land, chemicals, energy), targets, PDCA, audits', 'SA8000: working conditions in mines, health & safety, no child labour, freedom of association; supplier requirements', 'Stakeholder dialogue, monitoring of water tables', 'Certification by third parties'], []),
      B('weight', 'The company uses the GHG Protocol and the Swiss weighting method. What are the differences, what is their scope?', ['GHG Protocol: accounting of GHG only (Scopes 1–3, CO₂-eq, organisational boundary)', 'Ecological scarcity (UBP): single score over many emissions and resources incl. water (relevant here!)', 'GHG: accepted, simple, one issue', 'UBP: broad, but Swiss policy weights', 'Use both for different purposes'], []),
    ] });

  C({ id: 'bread', icon: '🍞', title: 'Bread from wheat', src: 'Exam HS12, paraphrased',
    intro: '<p>A bakery chain produces bread from wheat: <b>farming</b> (fertilizer, fungicides), <b>milling</b> (flour; bran and waste flour as by-products), <b>baking</b>, retail, consumption. The <b>retailer sells only ~90 %</b> of the bread; the rest goes to animal feed at a low price. Fungicides are also used during <b>grain storage</b>. Every evening there is a bread overload in the stores. The chain wants to lower its impacts with the help of LCA.</p>',
    tips: 'Allocation of the bread to animal feed + avoided burden in detail; Braunschweig: EMS for a bakery and a SMART target on food waste.',
    q: [
      P('fu', 'What could be a suitable functional unit for the bread production?', ['1 kg of fresh bread at the retailer (defined type, e.g. wholemeal)', 'Or nutritional basis (kcal, protein) for comparisons with other staples', 'Consider losses: bread actually eaten vs. produced', 'Time/region (season, Switzerland)'], []),
      P('basics', 'Which processes would be included in the LCA of the bread?', ['Agriculture (fertilizer, pesticides, machinery, land, N₂O)', 'Transport, storage (fungicides), milling (by-products)', 'Baking (energy), packaging, retail (cooling), consumer transport, waste', 'Infrastructure (optional), background: energy, chemicals'], []),
      P('alloc', 'The retailer gives 10 % of the bread as animal feed for a low price. What is the problem and how would you allocate? Explain avoided burden in detail.', ['Multifunctionality: food for humans + feed', 'System expansion/avoided burden: identify feed replaced (e.g. barley, soy), amount (nutritional equivalence), its impacts → credit', 'Physical or economic allocation (low price → small share)', 'Consequential: does bread waste change production volumes?'], []),
      P('io', 'What are the differences between IO analysis and process LCA? Can you include environmental concerns in the IO table?', ['pLCA detailed, physical, truncation; IO complete, monetary, aggregated', 'Hybrid LCA', 'Yes: satellite matrix with emissions per CHF below the economic table', 'Also social issues as extra rows'], []),
      P('risk', 'What is important if fungicides are used during storage, and if they are used during production of the wheat?', ['Storage: residues in food → human exposure (intake, ADI), indoor exposure of workers', 'Production: emissions to soil, water, air → fate (volatility, mobility, degradation, metabolites) → ecotox exposure and effect', 'Concentration addition for mixtures', 'RA (PEC/PNEC) vs. LCA (USEtox)'], []),
      P('clca', 'In Japan people would eat bread instead of rice. Which approach would you use and how?', ['Consequential LCA (large change in demand)', 'Marginal wheat suppliers (imports), reduced rice production', 'Land use change, market effects', 'Scenarios'], []),
      B('ems', 'Draw and explain an environmental management system for the bakery.', ['ISO 14001 cycle: context, compliance, leadership, policy, plan, do, check, act', 'Bakery aspects: energy (ovens), food waste, flour sourcing, packaging, transport', 'Responsibility, targets, monitoring', 'Continual improvement'], []),
      B('targets', 'The goal is to reduce the bread overload. What could be the target? What do you need to consider?', ['SMART: "Reduce unsold bread per store by 30 % by end of 2027 vs. 2025; responsible: store managers"', 'KPI kg unsold per store and day; baseline', 'Measures: forecasting, assortment in the evening, discounts, donations', 'Relevance: environmental and cost impact'], []),
      B('supply', 'Which standards and principles do you know for corporate sustainability (e.g. GRI, Global Compact) and what do they cover?', ['GRI: reporting standards (economic, environmental, social indicators)', 'UN Global Compact: 10 principles (human rights, labour, environment, anti-corruption)', 'ISO 14001, SA8000, ISO 26000', 'Elements of corporate sustainability: strategy, stakeholders, targets in all dimensions, measurement, communication'], []),
    ] });

  C({ id: 'concrete', icon: '🧱', title: 'Recycled concrete wall with CO₂ uptake', src: 'Exam 2022, paraphrased',
    intro: '<p>A comparative LCA of a <b>traditional concrete wall</b> and a <b>recycled concrete wall</b>. The recycled wall uses recycled concrete aggregates and absorbs <b>liquefied CO₂ captured at a wastewater treatment plant</b> during curing. Tables show the material amounts per wall and the GHG emissions of each material. The producer has set GHG targets for the recycled wall.</p><p class="small muted">Fictive data per wall (1 m², same load capacity):</p>',
    data: [['Material', 'Traditional [kg]', 'Recycled [kg]', 'g CO₂-eq/kg'], ['Cement', '60', '55', '820'], ['Natural aggregates', '400', '100', '5'], ['Recycled aggregates', '0', '300', '3'], ['CO₂ stored during curing', '–', '−5 kg', '–'], ['Result (sum)', '≈ 51 kg', '≈ 41 kg', '']],
    tips: 'System boundary incl. the origin of the CO₂; critique of EOR (credits!); pedigree + variability of the cement plants; judging SMART targets.',
    q: [
      P('fu', 'Define a functional unit for comparing the two walls.', ['1 m² of wall with identical load-bearing capacity, thermal/acoustic performance and fire safety', 'Over a defined service life (e.g. 50 years) incl. maintenance', 'Not "1 m³ concrete" or "1 kg" – the mixes and thicknesses may differ', 'Reference flows: kg of each material per m² (table)'], []),
      P('basics', 'Which system boundaries do you set for this comparative LCA?', ['Same FU: 1 m² wall with equal load-bearing capacity and lifetime (50 a)', 'Cradle-to-grave: raw materials, cement, aggregates (natural/recycled), CO₂ capture, liquefaction & transport, production, construction, use (carbonation), demolition, EoL', 'Multifunctional CO₂ supply: who gets the credit (WWTP or wall)? Avoid double counting', 'Permanence of CO₂ storage', 'Cut-off criteria, documentation'], []),
      P('alloc', 'Explain the end-of-life recycling (avoided burden) modelling for recycling concrete and the critique of it.', ['EOR: credit for avoided primary aggregates (and cement?) in future products', 'Offsetting position for the user of recycled aggregates', 'Weak sustainability; "environmental loan"', 'Critique: hides today\'s emissions; sunk impacts; future credits uncertain and smaller (decarbonization); credits for aggregates are small vs. cement', 'Alternatives: cut-off; EN 15804 module D separately'], [['Which environmental credits are involved?', 'Avoided natural aggregates, avoided landfill, possibly avoided CO₂ capture alternatives – and the claimed CO₂ storage.']]),
      P('unc', 'There are uncertainties in the conditions of the concrete plants and their flue gas treatment. Which uncertainty sources exist in the LCI, and how do you deal with them?', ['Parameter uncertainty (fuel, clinker ratio, emission factors)', 'Variability between plants (technology, flue gas treatment), temporal & spatial', 'Data quality: pedigree matrix → lognormal distributions', 'Monte Carlo; scenarios for choices; sensitivity analysis', 'Without expert judgement: conservative default scores, literature ranges, boundary analysis'], []),
      B('targets', 'From the tables, the producer set targets for the overall GHG emissions of the recycled wall. How "SMART" and how relevant are these targets?', ['Specific & measurable: kg CO₂-eq per m² – yes, if FU and boundaries are clear', 'Time-bound? Baseline? Responsibility?', 'Relevance: cement dominates – target should address clinker ratio, not only aggregates', 'Credibility of the CO₂ uptake credit (permanence, double counting)', 'GHG-only: other impacts (dust, land, resources) missing'], []),
      B('ghg', 'The producer wants to advertise the wall as "climate positive". How do you assess this claim?', ['Inventory boundaries and method (ISO 14067 for products)', 'Credits: is the captured CO₂ fossil or biogenic? Would it be emitted otherwise? Permanence', 'Reduction vs. compensation; verification', 'EU rules on green claims (no misleading neutrality claims)', 'Comparative public claim → critical review'], []),
    ] });

  C({ id: 'lyocell', icon: '🧵', title: 'Lyocell fabrics by "beechtex"', src: 'Exam 2022, paraphrased',
    intro: '<p><b>beechtex</b> produces <b>lyocell</b> fabrics. Lyocell is a wood-based fibre similar to viscose and can replace cotton in textiles. beechtex grows its <b>own trees in Australia</b>. For viscose, <b>carbon disulphide (CS₂)</b> is used, very toxic for workers and the environment; lyocell uses <b>N-methylmorpholine N-oxide (NMMO)</b> in a closed loop – higher costs, lower toxicity. The company states it is "<b>climate neutral</b>".</p>',
    tips: 'Key word for the rebound: price elasticity! For "climate neutral": ISO 14064, Scopes 1–3, view offsetting critically.',
    q: [
      P('fu', 'Define a functional unit to compare lyocell with cotton and viscose fabrics.', ['Function: textile for garments with equal quality (strength, comfort, durability)', 'e.g. 1 T-shirt (or 1 m² fabric of defined weight) worn X times incl. washing', 'Lifetime and washing behaviour may differ → time/use dimension', '1 kg fibre only for cradle-to-gate comparisons of identical quality'], []),
      P('basics', 'How would you assess the cradle-to-grave life cycle of the lyocell fabrics?', ['FU e.g. 1 garment used X times (or 1 kg fabric with equal quality)', 'Stages: forestry (land use, water), pulp, fibre (NMMO, recovery rate, energy), spinning/weaving, dyeing, use (washing), end of life', 'Sourcing of wood, transport from Australia', 'Allocation (pulp by-products, recycling of solvent, textile recycling)', 'Impact categories beyond GHG: toxicity, water, land'], []),
      P('lcia', 'Which impacts need to be regionalized? How and why?', ['Land use / biodiversity (plantations in Australia vs. cotton fields)', 'Water use (AWARE; cotton irrigation for comparison)', 'Toxicity (CS₂ vs. NMMO emissions near plants)', 'Need regionalized LCI (site locations) and CFs', 'Climate change: global'], []),
      P('clca', 'Explain the rebound effect and how it can be included for lyocell. Which data would you use?', ['Cheaper/greener fibre → more consumption or replacing other fibres', 'Price elasticity of demand (key word!)', 'Re-spending effects via EE-IO', 'Consequential: which fibre is displaced (cotton, viscose, polyester)', 'Data: market and price statistics, elasticities, MRIO intensities'], []),
      B('ghg', 'The company states it is "climate neutral". How would you assess the overall impact of the company and its production?', ['GHG accounting according to ISO 14064-1 / GHG Protocol', 'Scope 1 (own boilers, processes), Scope 2 (electricity), Scope 3 (forestry, chemicals, transport, use, EoL)', 'Climate neutral = residual emissions offset: check reductions, offset quality, verification (ISO 14068-1)', 'Not "no fossil fuels"', 'Other impacts remain → complement with LCA/ecobalance'], [['Which impacts are included in Scopes 1 to 3?', 'Direct; purchased energy; all other indirect value chain emissions (15 categories).']]),
      B('econ', 'Which stakeholders and which material topics (double materiality) would you consider for beechtex?', ['Stakeholders: customers/brands, workers, local communities in Australia, investors, NGOs, authorities', 'Inside-out: land use & biodiversity, water, chemicals, GHG', 'Outside-in: regulation (EU textile strategy, green claims), resource risks, costs of NMMO', 'CSRD requires both views'], []),
    ] });

  C({ id: 'wastewater', icon: '🚰', title: 'Industrial wastewater treatment (overarching case)', src: 'Exercise task 5 / lecture 14',
    intro: '<p>A chemical production site decides how to treat a new wastewater mix with non-degradable pollutants. <b>System 1</b>: nanofiltration (NF), high-pressure wet-air oxidation (WAO) with ammonia recovery, mechanical-biological treatment (MBT), sludge incineration (SI). <b>System 2</b>: NF, MBT, SI. WAO and SI generate <b>excess steam</b> (site heating or district heating); WAO also recovers <b>NH₃ solution</b> that substitutes primary NH₃. The processes need electricity, steam and auxiliary chemicals.</p>',
    data: [['Parameter', 'Influent', 'Elimination System 1', 'Elimination System 2', 'CF [kg benzene-eq/kg]'], ['TOC', '1 g/L', '95 %', '90 %', '10'], ['Cu total', '0.02 g/L', '93 %', '87 %', '6.9'], ['N total', '0.1 g/L', '–', '–', '–'], ['PO₄³⁻', '0.001 g/L', '–', '–', '–']],
    tips: 'Pfister: "It is a good exam preparation." Calculate the ecotox values during the preparation (0.51 vs. 1.02 kg benzene-eq/m³).',
    q: [
      P('fu', 'Define an appropriate functional unit and list the processes to be considered.', ['Purification of 1 m³ wastewater of the given composition to the legally required effluent quality', 'System 1: NF, WAO (+ NH₃ recovery), MBT, SI; System 2: NF, MBT, SI', 'Background: electricity, steam, chemicals (precipitant), transport, disposal', 'Co-products: steam, NH₃'], []),
      P('alloc', 'How can you ensure equal service of both systems? How do you deal with the co-products? Discuss modelling options.', ['Equal service: same FU, same effluent quality (TOC, Cu, N, P), sludge handled', 'Co-products steam (both) and NH₃ (System 1)', 'System expansion/avoided burden: credit for avoided steam (which reference system: site gas boiler or district heat?) and avoided primary NH₃', 'Economic allocation (e.g. ~94 % treatment, ~6 % steam)', 'Pros/cons: system expansion comprehensive but depends on assumptions; economic simple but price-dependent'], []),
      P('basics', 'Where do you retrieve which inventory data from? What is foreground and background?', ['Foreground: primary data – operator, monitoring of emissions, accounting, sustainability department, plant documentation', 'Background: LCI databases (ecoinvent) for electricity, chemicals, steam; IO/MRIO; literature', 'Data quality assessment (pedigree)'], []),
      P('lcia', 'Quantify the ecotoxicological impact of the direct Cu and TOC emissions per m³. Are TOC emissions relevant? Why are they often neglected?', ['System 1: TOC 0.05 kg × 10 = 0.5; Cu 0.0014 kg × 6.9 = 0.0097 → 0.51 kg benzene-eq/m³', 'System 2: TOC 0.1 × 10 = 1.0; Cu 0.0026 × 6.9 = 0.018 → 1.02', 'TOC dominates here → relevant', 'Often neglected: sum parameter, no CFs for unknown substance mix, data gaps', 'System 1 better for direct ecotox; check indirect impacts (energy for WAO)'], []),
      P('lcia', 'Is regionalization necessary in this case?', ['Ecotoxicity of effluent depends on receiving river (dilution, sensitivity) → yes for direct emissions', 'Electricity and steam background: regional mixes', 'Climate change: no'], []),
      P('unc', 'Which uncertainties exist in the background data and how do you handle them?', ['Few data points → pedigree matrix, lognormal', 'Many data → fit distributions', 'Monte Carlo propagation; percentile ranges', 'Scenario uncertainty (allocation, reference system for steam)'], []),
      P('dec', 'How could optimization help to design the treatment network? Formulate objective and constraints.', ['Objective: min environmental impacts and/or cost', 'Constraints: treat all wastewaters; given module network; treatment efficiency per module; capacity limits; pollution limits per stream', 'Decision variables: flows to each module', 'Multi-objective → Pareto front'], []),
      B('lcc', 'The environmental manager also wants to compare costs. How would you set up an LCC of the two systems?', ['Same FU (1 m³) and time frame (plant lifetime)', 'Investment, energy, chemicals, maintenance, sludge disposal, revenues from steam and NH₃', 'Discounting of conventional costs', 'Environmental LCC: external costs of emissions', 'Portfolio LCC vs. LCA'], []),
    ] });

  C({ id: 'tshirt', icon: '👕', title: 'Football club T-shirts: organic cotton vs. recycled PET', src: 'Older protocol, paraphrased',
    intro: '<p>A football team wants to sell T-shirts to its supporters. They can be made of <b>organic cotton</b> or <b>recycled PET</b>. To decide, the club commissions an LCA. Data for cotton farming come partly from a single farm in Asia, other parameters are continental averages. The suppliers do not want to disclose their process data.</p>',
    tips: 'Typical mix: LCIA chain in detail, unit vs. system process, transparency and review, 6 types of uncertainty; Braunschweig: standards, ISO 14001, SA8000, GRI.',
    q: [
      P('fu', 'Define the functional unit.', ['One T-shirt (size M) worn X times or for one season, incl. washing', 'Durability differs (cotton vs. PET)', 'Equal quality (comfort, print)'], []),
      P('lcia', 'Which impact categories should be considered? Which of them need regionalized assessment and why?', ['Land use, water use, ecotoxicity (pesticides – fewer for organic), climate change, eutrophication, microplastics (PET)', 'Regionalized: land, water (AWARE), toxicity, eutrophication', 'Global: climate change'], []),
      P('lcia', 'How do you calculate the global warming score? How is the first step modelled? What are midpoint and endpoint?', ['Emissions → concentration (one-box model, complete mixing) → radiative forcing → temperature → HH/EQ damage', 'Midpoint: GWP (RF level) in kg CO₂-eq', 'Endpoint: DALY and species·yr'], []),
      P('basics', 'What is a unit process approach vs. a system process approach? What are the inputs and outputs in each case?', ['Unit: single process, technosphere inputs + direct emissions', 'System: aggregated cradle-to-gate, only elementary flows', 'Transparency vs. confidentiality'], []),
      P('review', 'Data transparency vs. confidentiality: what do you recommend here? What does a critical review verify?', ['Suppliers protect data → aggregated/anonymised publication, internal calculation', 'Critical review verifies consistency with ISO, validity, appropriateness of data (e.g. comparing with sources, fit to goal), interpretation, transparency', 'Review no full substitute for transparency'], []),
      P('unc', 'Which uncertainties exist? Land use: one precise value from one farm in Asia, other parameters for the whole continent – how do you deal with this?', ['6 types: parameter, model, scenario; spatial, temporal, between objects', 'Mismatch of spatial resolution → representativeness (pedigree: geographical correlation)', 'Use consistent resolution or regionalize all parameters; sensitivity', 'Monte Carlo explained (random draws, many runs, output distribution)'], []),
      B('supply', 'Which standards exist for the four dimensions of sustainability (quality, environment, social, finance)?', ['ISO 9001 / EFQM', 'ISO 14001, EMAS, ISO 14064, ISO 50001', 'SA8000, ISO 26000, ISO 45001', 'IAS/IFRS, Swiss GAAP FER', 'Reporting: GRI'], []),
      B('ems', 'What does ISO 14001 require? What does it tell you if a supplier complies with it? Draw the EMS.', ['Cycle: context, compliance, leadership, policy, plan, do, check, act', 'Significant aspects, objectives, monitoring, audits, management review', 'Supplier with ISO 14001: functioning system – not a guaranteed performance'], []),
      B('supply', 'Give examples of issues covered by SA8000 and explain the GRI standards.', ['SA8000: child & forced labour, health & safety, freedom of association, discrimination, discipline, working hours, wages, management system', 'GRI: reporting framework with economic, environmental and social indicators; materiality'], []),
      B('targets', 'Give an example of an environmental target for the club\'s merchandising.', ['"By 2027, 100 % of club T-shirts from certified organic cotton or recycled PET with EPD/ecolabel; responsible: merchandising manager"', 'SMART check, relevance (textiles are the main merchandising impact)'], []),
    ] });

  C({ id: 'coffee', icon: '☕', title: 'Café chain: Brazilian espresso & aluminium capsules', src: 'New practice case (cf. "LCA of Brazilian coffee")',
    intro: '<p>A Swiss café chain (80 outlets in CH and the EU) sells espresso made from <b>Brazilian coffee</b>: farming in Minas Gerais (some regions irrigated, fertilizer, pesticides, past land-use change), processing at the farm (<b>coffee husks and pulp</b> as by-products, partly used as fuel or fertilizer), shipping, roasting in Switzerland, preparation in the outlets (machine electricity, milk for cappuccino). For retail, the coffee is sold in <b>aluminium capsules</b> with a take-back system (60 % returned and recycled). The chain wants to set <b>science-based targets</b> and must report under <b>CSRD</b>.</p>',
    data: [['Fictive data per espresso (40 ml)', 'Value'], ['Green coffee', '7.5 g (≈ 9 g cherries dried)'], ['Climate: farming', '≈ 30 g CO₂-eq'], ['Climate: milk (cappuccino)', '≈ 150 g CO₂-eq per 120 ml'], ['Capsule', '1 g aluminium'], ['Irrigation water (some regions)', '0.2 L, AWARE CF 1–40']],
    tips: 'New, but in the style of the exam: FU (per cup!), allocation of the by-products, recycling of the capsule (RC vs. EOR), regionalizing water; company: scopes, SBTi, CSRD, supply chain.',
    q: [
      P('fu', 'Define a functional unit for comparing capsule espresso with espresso from the outlet machine.', ['One cup of espresso (40 ml) of comparable quality/taste', 'Or one cappuccino if milk is included – keep systems equal', 'Include preparation, cup washing, capsule end of life', 'Reference flows: g coffee, capsule, kWh'], []),
      P('basics', 'Which life cycle stages and hotspots do you expect?', ['Farming (fertilizer N₂O, land-use change, pesticides), processing', 'Milk often dominates for milk drinks', 'Capsule aluminium (primary production energy-intensive)', 'Preparation electricity (standby!), transport minor', 'Contribution and sensitivity analysis'], []),
      P('alloc', 'Coffee processing produces husks and pulp used as fuel or fertilizer. How do you allocate?', ['ISO hierarchy', 'System expansion: credit avoided fuel/fertilizer', 'Economic allocation: low value → small share to by-products', 'Sensitivity'], []),
      P('alloc', 'How do you model the recycling of the aluminium capsules (60 % returned)? Compare cut-off and avoided burden.', ['Cut-off: capsule carries primary aluminium (minus recycled content); no credit', 'EOR: credit 60 % × avoided primary aluminium minus recycling burden; offsetting position for recycled input', 'EN 15804-style module D separately', 'Strong vs. weak sustainability; results can differ by factor 2'], []),
      P('lcia', 'Why and how would you regionalize water use for coffee?', ['Irrigation only in some regions; scarcity varies strongly (AWARE 1–40)', 'Need location of farms (LCI) + regional CFs', 'Within-country variability can exceed between-country variability', 'Also land use and biodiversity (Cerrado)'], []),
      P('unc', 'Farm data come from a few farms. How do you deal with data quality and uncertainty?', ['Variability between farms (yields, fertilizer, irrigation)', 'Pedigree for single values; distributions from samples', 'Monte Carlo; sensitivity on yields and N₂O factors', 'Collect primary data from main suppliers'], []),
      B('ghg', 'Which emissions fall into Scope 1, 2 and 3 for the café chain? Where is the largest share?', ['Scope 1: gas for roasting (if own), company vehicles, refrigerant leaks', 'Scope 2: electricity of outlets and roastery', 'Scope 3: purchased coffee and milk (cat. 1) – largest; capsules; transport; waste; use of sold capsules (cat. 11) and end of life (cat. 12)', 'SBTi: Scope 3 target needed (> 40 % share)'], []),
      B('econ', 'Under CSRD the chain must assess double materiality. Which topics would you expect?', ['Inside-out: climate (farming, milk), deforestation/land use, water, pesticides, packaging waste, workers\' rights on farms', 'Outside-in: climate risks for coffee supply (yield, prices), EU deforestation regulation, consumer expectations, packaging rules', 'Stakeholder dialogue and data from LCA'], []),
      B('supply', 'How would you manage social risks in the Brazilian supply chain?', ['Risk check (labour conditions, child labour, wages on farms)', 'Code of conduct signed by suppliers → but "paper is patient"', 'Audits, training, long-term contracts, fair prices; certifications (Fairtrade, Rainforest Alliance)', 'Clear consequences; report (GRI, CSRD)'], []),
    ] });

  C({ id: 'hotel', icon: '🏨', title: 'Hotel Walliserhof: KPIs, heating & management', src: 'New case based on homework case 3',
    intro: '<p>The 4*-superior hotel <b>Walliserhof</b> in Leukerbad (1,700 m a.s.l.): 80 rooms, 164 beds, open mid-June to end of April (46 weeks), turnover 7.84 M CHF, 62–71 employees, 29,800 overnight stays and 115,000 warm meals per year. The old <b>oil heating</b> must be replaced either by an <b>air-water heat pump</b> or a <b>wood-pellet boiler</b>. The owner wants a sustainability orientation for the hotel.</p>',
    data: [['KPI (example solution)', 'per service unit*'], ['Electricity', '9.8 kWh'], ['Heat', '23.5 kWh'], ['Water', '180 L'], ['Solid waste', '0.88 kg'], ['*Service unit', 'overnight stays + ⅓ × warm meals = 68,133']],
    tips: 'Company-heavy case: Pfister part on the heating LCA (FU, particulate matter is regional!), then Braunschweig: reasons, aspects, stakeholders, responsibility, KPIs, LCC.',
    q: [
      P('fu', 'Define the functional unit for comparing the heat pump and the pellet boiler.', ['Supply of X MWh useful heat per year (space heating + hot water) to the hotel at 1,700 m, over 20 years', 'Same comfort level and reliability (peak demand in winter)', 'Include energy supply chains (electricity mix, pellets)'], []),
      P('lcia', 'Which impact categories are relevant and which need regionalization?', ['Climate change (electricity mix vs. biogenic CO₂ of pellets)', 'Particulate matter from pellet combustion in an alpine valley – strongly regional (inversions, population)', 'Land use / forestry for pellets', 'Resource use, refrigerant leakage of the heat pump'], []),
      P('unc', 'The heat pump performance (COP) at 1,700 m is uncertain. How do you handle it?', ['Parameter uncertainty and temporal variability (cold winters)', 'Distribution for seasonal COP (data from similar sites)', 'Monte Carlo; scenario with backup heating', 'Sensitivity: electricity mix (CH consumer mix vs. marginal winter electricity)'], []),
      B('mgmt', 'Which reasons may lead a hotel to a sustainability orientation? What do sustainable hotels give as reasons?', ['Cost savings (energy, water, waste)', 'Guest expectations, labels, tour operators', 'Image and differentiation; staff motivation', 'Regulation (CO₂ levy, energy law)', 'Responsibility for the alpine landscape (tourism depends on it)'], []),
      B('targets', 'ISO 14001 asks to identify the relevant environmental aspects. Which criteria would you use?', ['Quantity × environmental relevance (ecobalance: heating, electricity, water/wellness, food, waste, laundry, guest travel)', 'Legal requirements; costs', 'Stakeholder expectations; risks', 'Control vs. influence; improvement potential'], []),
      B('targets', 'In which areas can a hotel create positive societal effects? Who should be responsible for environmental management?', ['Local jobs and apprenticeships, local suppliers, culture, community, guest awareness', 'Responsibility: director (top management) with a responsible person/team; involve chef de cuisine, gouvernante, technical service', 'Targets in job descriptions'], []),
      B('lcc', 'How would you compare the two heating options economically?', ['LCC over 20 years: investment, energy (electricity vs. pellets), maintenance, chimney/sweeping, replacement, residual value', 'Discounting; scenarios for energy prices and CO₂ levy', 'Environmental LCC: external costs (PM health, CO₂)', 'Same heat demand (FU)'], []),
      B('weight', 'The owner asks: "Should we just report CO₂ or a single score?" What do you answer?', ['CO₂ only: simple, accepted, but pellets look perfect while PM is ignored → burden shifting', 'Single score (UBP): covers PM and other impacts, supports the decision, but value-based', 'Recommendation: decide with UBP + key categories, communicate measures with physical KPIs (kWh, litres)'], []),
    ] });

  C({ id: 'compressor', icon: '❄️', title: 'Stoffel AG: cooling compressors', src: 'Homework case 4 + new LCA questions',
    intro: '<p><b>Peter Stoffel AG</b> (30 employees) distributes and services cooling compressors of three brands for professional refrigerators (retail). Its direct clients are about 8 refrigerator producers, which are very price-sensitive. Compressor prices with similar cooling power differ by a factor of two; electricity efficiency varies; average lifetime is 10 years. The CEO thinks Stoffel is too small to influence suppliers or end users.</p>',
    data: [['', 'Moreland FE12', 'Moreland FE18', 'Sheeter PBa'], ['Price [CHF]', '7,300', '14,200', '9,100'], ['Cooling capacity', '10 kW', '13 kW', '10 kW'], ['Electricity consumption', '13 kW', '10 kW', '8 kW'], ['Refrigerant refill (lifetime)', '110 kg R404A', '100 kg R404A', '120 kg R507A'], ['All', 'needed: 10 kW cooling, 24 h × 365 d, 10 years, 0.15 CHF/kWh, 50 CHF/kg refrigerant', '', '']],
    tips: 'The FE18 is oversized: for 10 kW of cooling it needs only 7.7 kW of electricity. Market LCC: 183,620 / ≈ 120,300 / 120,220 CHF. "Active products" → the use phase dominates.',
    q: [
      P('fu', 'Define a functional unit for the LCA of the compressors.', ['Providing 10 kW cooling capacity continuously (24 h × 365 d) for 10 years', 'Same temperature level and reliability', 'Reference flows: 1 compressor + electricity + refrigerant refills'], []),
      P('basics', 'Which life cycle phase dominates and why? What does this mean for the LCA?', ['Use phase: electricity (≈ 0.7–1.1 GWh over 10 years) and refrigerant leakage', '"Active product": production and EoL minor', 'Hotspots → efficiency and refrigerant choice', 'Electricity mix choice is a key parameter (sensitivity)'], []),
      P('lcia', 'Which impacts does the refrigerant leakage cause? How large is it compared with the electricity?', ['R404A/R507A are HFCs: high GWP (≈ 3,900), no ozone depletion', '110 kg × 3,922 ≈ 430 t CO₂-eq vs. electricity 1.14 GWh × 0.1 kg/kWh ≈ 114 t (CH mix)', 'Refrigerant can dominate climate impact → recovery at EoL, low-GWP refrigerants', 'Depends strongly on electricity mix'], []),
      P('clca', 'If Stoffel promotes efficient compressors, which electricity savings would you account for?', ['Consequential view: marginal electricity (which production reacts to lower demand?)', 'Average vs. marginal mix changes the result', 'Rebound: lower operating costs → more cooling devices?', 'Scenario analysis'], []),
      B('lcc', 'Calculate the life cycle (market) cost of the three compressors and interpret.', ['FE12: 7,300 + 170,820 (13 kW) + 5,500 = 183,620 CHF', 'FE18: 14,200 + ≈ 101,100 (7.7 kW for 10 kW cooling) + 5,000 ≈ 120,300 CHF', 'PBa: 9,100 + 105,120 + 6,000 = 120,220 CHF', 'Purchase price is almost irrelevant/misleading; use phase dominates', 'With external costs (CO₂, refrigerant) differences grow'], []),
      B('lcc', 'Which environmental opportunities do you see for Stoffel\'s market approach? How could an LCM/LCC approach help, and how would Stoffel reach its stakeholders?', ['Promote efficient brands with total cost of ownership', 'LCC/LCM consulting for refrigerator producers and their clients (retailers)', 'Differentiation, customer loyalty', 'Channels: existing networks, associations, trade fairs; arguments: long-term savings + environmental benefits', 'R&D/selection of low-GWP refrigerants'], []),
      B('ghg', 'In which Scope 3 category would the use-phase electricity of the sold compressors appear for Stoffel, and why does it matter?', ['Scope 3, category 11: use of sold products', 'By far the largest part of Stoffel\'s footprint', 'Science-based targets would require engagement on product efficiency', 'Shows the leverage of a small distributor'], []),
    ] });
})();
